#!/usr/bin/env bash
#
# prepare_test_fixtures.sh — materialise and verify the workspace's golden test data.
#
# Canonical fixtures live in the crate that consumes them (`crates/<crate>/testdata/`),
# generated by the oracle programs under `crates/<crate>/testdata/generators/`. Test code
# reads them two ways, and this script serves both:
#
#   * compile time — `include_str!("../testdata/<file>")` embeds the bytes in the test
#     binary, so a `cargo test` never looks for a file at run time;
#   * run time — a test that needs a *path* rather than embedded bytes (a later milestone's
#     on-disk check against a real retail file, or anything that streams a large fixture)
#     reads `<target>/testdata/<crate>/`.
#
# Because those two readers must never disagree, the script copies the canonical tree into
# the target directory and then verifies BOTH the canonical files and the copies against
# `fixtures.manifest` (name, bytes, FNV-1a/64).
#
# Each crate also carries `fixtures.provenance`: one block per fixture recording the oracle it
# came from, the derivation steps, and the seed (planning/05 §3 rule 1). A fixture that loses
# its provenance is a fixture nobody can re-derive, so the script treats missing or incomplete
# provenance as a failure, not as a documentation gap.
#
# Usage:
#   scripts/prepare_test_fixtures.sh              # copy, then verify
#   scripts/prepare_test_fixtures.sh --check      # verify only (what CI and `make test` run)
#   scripts/prepare_test_fixtures.sh --write      # rewrite the manifest from the canonical files
#
# Exit status is non-zero when a fixture is missing, extra, unprovenanced, or has different
# bytes than the manifest records. A fixture is never silently repaired: `--write` is a
# deliberate act, so that a refreshed oracle shows up as a change a person reviewed.

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
MODE="${1:-prepare}"
TARGET_DIR="${CARGO_TARGET_DIR:-$ROOT/target}/testdata"

case "$MODE" in
    --check)  CHECK_ONLY=1; WRITE=0 ;;
    --write)  CHECK_ONLY=0; WRITE=1 ;;
    prepare)  CHECK_ONLY=0; WRITE=0 ;;
    *) echo "usage: $0 [--check|--write]" >&2; exit 2 ;;
esac

# The digest is FNV-1a/64 over the raw bytes, computed here and in tests/fixtures.rs. It is
# not a security primitive; it exists so that "the file changed" is a checkable fact rather
# than something noticed when a golden test fails for an unrelated-looking reason.
python3 - "$ROOT" "$MODE" "$TARGET_DIR" <<'PY'
import os
import sys

root, mode, target_dir = sys.argv[1], sys.argv[2], sys.argv[3]

FNV_OFFSET = 0xCBF29CE484222325
FNV_PRIME = 0x100000001B3

PROVENANCE_REQUIRED = ("oracle", "derivation", "seed")


def digest(path):
    value = FNV_OFFSET
    with open(path, "rb") as handle:
        for chunk in iter(lambda: handle.read(65536), b""):
            for byte in chunk:
                value ^= byte
                value = (value * FNV_PRIME) & 0xFFFFFFFFFFFFFFFF
    return f"{value:016x}"


def crate_data_dir(crate):
    return os.path.join(root, "crates", crate, "testdata")


def read_manifest(directory):
    entries = {}
    path = os.path.join(directory, "fixtures.manifest")
    if not os.path.isfile(path):
        return entries
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            name, size, digest_value = (part.strip() for part in line.split(","))
            entries[name] = (int(size), digest_value)
    return entries


def read_provenance(directory):
    """Parse `[file]` blocks with `key = value` lines into {file: {key: value}}."""
    blocks = {}
    path = os.path.join(directory, "fixtures.provenance")
    if not os.path.isfile(path):
        return blocks
    current = None
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if line.startswith("[") and line.endswith("]"):
                current = line[1:-1].strip()
                blocks[current] = {}
            elif "=" in line and current is not None:
                key, value = (part.strip() for part in line.split("=", 1))
                blocks[current][key] = value
    return blocks


def fixture_files(directory):
    if not os.path.isdir(directory):
        return []
    return sorted(
        name
        for name in os.listdir(directory)
        if name.endswith(".txt") and os.path.isfile(os.path.join(directory, name))
    )


def provenance_problems(crate, present, provenance):
    """Every fixture must declare where its expected values came from, and nothing may
    declare provenance for a file that is not there."""
    if not provenance:
        return [f"{crate}: no fixtures.provenance — every fixture must record oracle, "
                f"derivation and seed"]
    problems = []
    for name in present:
        record = provenance.get(name)
        if record is None:
            problems.append(f"{crate}: {name} has no provenance block")
            continue
        missing = [key for key in PROVENANCE_REQUIRED if not record.get(key)]
        if missing:
            problems.append(f"{crate}: {name} provenance is missing {', '.join(missing)}")
    for name in sorted(provenance):
        if name not in present:
            problems.append(
                f"{crate}: provenance describes {name}, which is not in the fixture tree"
            )
    return problems


CRATES = [
    crate
    for crate in sorted(os.listdir(os.path.join(root, "crates")))
    if os.path.isdir(os.path.join(root, "crates", crate, "testdata"))
]

problems = []
report = []
totals = [0, 0]

for crate in CRATES:
    canonical = crate_data_dir(crate)
    present = fixture_files(canonical)
    provenance = read_provenance(canonical)
    totals[0] += len(present)
    totals[1] += sum(
        1
        for name in present
        if all(provenance.get(name, {}).get(key) for key in PROVENANCE_REQUIRED)
    )

    if mode == "--write":
        lines = [
            "# Golden test data registered for {}.".format(crate),
            "#",
            "# name, bytes, fnv1a64 — regenerated by scripts/prepare_test_fixtures.sh --write.",
            "# Every .txt file in this directory must be listed here and must carry a block in",
            "# fixtures.provenance; tests/fixtures.rs checks the embedded bytes against these",
            "# values, so an unregistered or edited fixture fails the suite instead of silently",
            "# changing what is being compared.",
            "#",
        ]
        for name in present:
            path = os.path.join(canonical, name)
            lines.append(f"{name}, {os.path.getsize(path)}, {digest(path)}")
        with open(os.path.join(canonical, "fixtures.manifest"), "w", encoding="utf-8") as handle:
            handle.write("\n".join(lines) + "\n")
        report.append(f"{crate}: manifest rewritten ({len(present)} fixtures)")
        problems.extend(provenance_problems(crate, present, provenance))
        continue

    registered = read_manifest(canonical)
    if not registered:
        problems.append(
            f"{crate}: no fixtures.manifest — run `prepare_test_fixtures.sh --write`"
        )
        continue

    for name in registered:
        if name not in present:
            problems.append(f"{crate}: {name} is registered but absent")

    for name in present:
        if name not in registered:
            problems.append(f"{crate}: {name} is present but not registered")
            continue
        path = os.path.join(canonical, name)
        expected = registered[name]
        actual = (os.path.getsize(path), digest(path))
        if actual != expected:
            problems.append(
                f"{crate}: {name} differs from the manifest "
                f"(expected {expected[0]} bytes {expected[1]}, "
                f"got {actual[0]} bytes {actual[1]})"
            )

    problems.extend(provenance_problems(crate, present, provenance))

    # The copies a run-time reader will use are checked against the same manifest, so a
    # stale or truncated copy cannot be the thing a test silently passes on. In --check the
    # target directory may simply not exist yet (a bare `cargo test` never populates it),
    # which is not a failure; a half-populated one is.
    destination = os.path.join(target_dir, crate)
    if mode == "prepare":
        os.makedirs(destination, exist_ok=True)
        for name in present:
            with open(os.path.join(canonical, name), "rb") as handle:
                content = handle.read()
            with open(os.path.join(destination, name), "wb") as handle:
                handle.write(content)
        report.append(
            f"{crate}: copied {len(present)} fixtures to "
            f"{os.path.relpath(destination, root)}"
        )
    if os.path.isdir(destination):
        for name in registered:
            expected = registered[name]
            copy = os.path.join(destination, name)
            if not os.path.isfile(copy):
                problems.append(f"{crate}: {name} is missing from the target directory")
            elif (os.path.getsize(copy), digest(copy)) != expected:
                problems.append(
                    f"{crate}: the copy of {name} in the target directory is not the "
                    f"canonical file"
                )

if report:
    print("\n".join(report))
if problems:
    print("\n".join(problems), file=sys.stderr)
    print(f"\n{len(problems)} fixture problem(s).", file=sys.stderr)
    sys.exit(1)

print(
    f"fixture check passed: {totals[1]}/{totals[0]} fixture(s) with provenance, "
    f"across {len(CRATES)} crate(s)"
)
PY
